export class InputMirrorWidthObserver {
  private ro?: ResizeObserver;

  constructor(
    private inputEl: HTMLInputElement,
    private mirrorEl: HTMLElement,
    private formatLength: (n: number) => string | undefined = (n) => `${n}px`,
  ) {}

  start() {
    if (this.ro) return;
    this.ro = new ResizeObserver(() => {
      this.syncWidth();
    });
    this.ro.observe(this.mirrorEl);
    // 初始同步一次，确保挂载后宽度正确
    this.syncWidth();
  }

  stop() {
    this.ro?.disconnect();
    this.ro = undefined;
  }

  updateMirrorText(text: string) {
    this.mirrorEl.textContent = text;
    // 如果 ResizeObserver 尚未就绪，兜底同步一次
    if (!this.ro) {
      this.syncWidth();
    }
  }

  private syncWidth() {
    const width = this.mirrorEl.offsetWidth + 1;
    this.inputEl.style.width = this.formatLength(width) || '';
  }
}
